  topic: 'Terra e Universo', subtopic: 'Inclinação do eixo, solstícios e equinócios',
  aliases: ['estacoes do ano', 'por que existem estacoes', 'solsticio', 'equinocio', 'inclinacao da terra', 'eixo da terra', 'verao e inverno', 'primavera outono'],
  summary: 'Descubra por que existem as estações do ano e por que é verão no Brasil quando é inverno na Europa.',
  intro: 'Não é a distância do Sol que causa o verão! O segredo está na inclinação da Terra.',
  objective: 'Explicar as estações do ano pela inclinação do eixo da Terra durante a translação, reconhecer solstícios e equinócios e as estações opostas nos dois hemisférios.',
  prerequisites: ['cie-sistema-solar'], next: ['cie-terra-camadas'],
  skills: { eixo: 'Inclinação do eixo', estacoes: 'As quatro estações', marcos: 'Solstícios e equinócios', hemisferios: 'Hemisférios opostos' },
