  aliases: ['sistema circulatorio', 'sistema cardiovascular', 'coracao', 'sangue', 'arterias', 'veias', 'capilares', 'hemacias', 'globulos brancos', 'plaquetas', 'pequena e grande circulacao', 'pressao arterial'],
